namespace sv_628932596f1940f9b089f07852dcaac7.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Patel", "Dr. Lee"];

    private static readonly Dictionary<string, List<string>> SlotsByDoctor = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Patel"] = ["9:30 AM", "10:30 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Lee"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync() => Task.FromResult(Doctors);

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        var slots = SlotsByDoctor.GetValueOrDefault(doctor, []);
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates server-side business rules. Returns a dictionary of field name → error messages.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Reject outstanding-balance email
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = ["Account has outstanding balance"];
        }

        // Reject self-pay with doctors that don't accept it
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors["Doctor"] = ["Selected doctor does not accept self-pay patients"];
        }

        // Reject taken time slot
        if (timeSlot == "10:00 AM")
        {
            errors["TimeSlot"] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_628932596f1940f9b089f07852dcaac7.Models;

public class PatientInfoModel
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string? Name { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Enter a valid email address.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone number is required.")]
    [Phone(ErrorMessage = "Enter a valid phone number.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Please select an insurance provider.")]
    public string? InsuranceProvider { get; set; }
}

public class AppointmentDetailModel : IValidatableObject
{
    [Required(ErrorMessage = "Please select a doctor.")]
    public string? Doctor { get; set; }

    [Required(ErrorMessage = "Please select a date.")]
    public DateOnly? Date { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string? ReasonForVisit { get; set; }

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (Date.HasValue && Date.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            yield return new ValidationResult(
                "Date must be in the future.", [nameof(Date)]);
        }
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_628932596f1940f9b089f07852dcaac7.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_628932596f1940f9b089f07852dcaac7.Models
@using sv_628932596f1940f9b089f07852dcaac7.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book an Appointment</h3>

@* ───── STEP 1: Patient Information ───── *@
<EditForm EditContext="step1Context" OnValidSubmit="HandleStep1Valid" FormName="step1">
    <DataAnnotationsValidator />
    <CustomValidator @ref="step1Validator" />

    <h5>Step 1: Patient Information</h5>

    <div class="mb-3">
        <label class="form-label">Patient Name</label>
        <InputText class="form-control" @bind-Value="patientInfo.Name" />
        <ValidationMessage For="() => patientInfo.Name" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <InputText class="form-control" @bind-Value="patientInfo.Email" />
        <ValidationMessage For="() => patientInfo.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone</label>
        <InputText class="form-control" @bind-Value="patientInfo.Phone" />
        <ValidationMessage For="() => patientInfo.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Insurance Provider</label>
        <InputSelect class="form-select" @bind-Value="patientInfo.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => patientInfo.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="submit" class="btn btn-primary">Next</button>
    }
</EditForm>

@* ───── STEP 2: Appointment Details ───── *@
@if (showStep2)
{
    <hr class="my-4" />
    <EditForm EditContext="step2Context" OnValidSubmit="HandleStep2Valid" FormName="step2">
        <DataAnnotationsValidator />
        <CustomValidator @ref="step2Validator" />

        <h5>Step 2: Appointment Details</h5>

        <div class="mb-3">
            <label class="form-label">Preferred Doctor</label>
            <InputSelect class="form-select" @bind-Value="appointmentDetail.Doctor"
                         @bind-Value:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => appointmentDetail.Doctor" />
        </div>

        <div class="mb-3">
            <label class="form-label">Date</label>
            <InputDate class="form-control" @bind-Value="appointmentDetail.Date"
                       @bind-Value:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="() => appointmentDetail.Date" />
        </div>

        <div class="mb-3">
            <label class="form-label">Time Slot</label>
            <InputSelect class="form-select" @bind-Value="appointmentDetail.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in availableSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => appointmentDetail.TimeSlot" />
        </div>

        <div class="mb-3">
            <label class="form-label">Reason for Visit</label>
            <InputTextArea class="form-control" @bind-Value="appointmentDetail.ReasonForVisit" rows="3" />
            <ValidationMessage For="() => appointmentDetail.ReasonForVisit" />
        </div>

        <button type="submit" class="btn btn-success me-2" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability & Book")
        </button>
        <button type="button" class="btn btn-outline-secondary" @onclick="GoBackToStep1">Back</button>
    </EditForm>
}

@if (isBooked)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully for <strong>@patientInfo.Name</strong>
        with <strong>@appointmentDetail.Doctor</strong>
        on <strong>@appointmentDetail.Date?.ToString("MMM dd, yyyy")</strong>
        at <strong>@appointmentDetail.TimeSlot</strong>.
    </div>
}

@code {
    private PatientInfoModel patientInfo = new();
    private AppointmentDetailModel appointmentDetail = new();

    private EditContext step1Context = default!;
    private EditContext step2Context = default!;
    private CustomValidator? step1Validator;
    private CustomValidator? step2Validator;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    private bool showStep2;
    private bool isSubmitting;
    private bool isBooked;

    protected override async Task OnInitializedAsync()
    {
        step1Context = new EditContext(patientInfo);
        step2Context = new EditContext(appointmentDetail);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void HandleStep1Valid()
    {
        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        appointmentDetail.TimeSlot = null;
        if (!string.IsNullOrEmpty(appointmentDetail.Doctor) && appointmentDetail.Date.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                appointmentDetail.Doctor, appointmentDetail.Date.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleStep2Valid()
    {
        isSubmitting = true;
        isBooked = false;

        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                patientInfo.Email!,
                patientInfo.InsuranceProvider!,
                appointmentDetail.Doctor!,
                appointmentDetail.TimeSlot!);

            if (errors.Count > 0)
            {
                step2Validator!.DisplayErrors(errors);

                // Show email errors on step 1 form
                if (errors.ContainsKey("Email"))
                {
                    step1Validator!.DisplayErrors(
                        new Dictionary<string, List<string>> { ["Email"] = errors["Email"] });
                }
                return;
            }

            isBooked = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void GoBackToStep1()
    {
        showStep2 = false;
        isBooked = false;
    }
}

